23	// Helper function for ceiling division
24	inline int64_t CeilDiv(int64_t a, int64_t b)
25	{
26	    if (b == 0) {
27	        return 0;
28	    }
29	    return (a + b - 1) / b;
30	}
31	
32	inline int64_t AlignDown(int64_t a, int64_t b)
33	{
34	    if (b == 0) {
35	        return 0;
36	    }
37	    return a / b * b;
38	}
39	
40	inline int64_t AlignUp(int64_t a, int64_t b)
41	{
42	    if (b == 0) {
43	        return 0;
44	    }
45	    return CeilDiv(a, b) * b;
46	}
47	// Constants
48	const static int64_t DEFAULT_WORKSPACE_SIZE = 16777216; // 16M预留空间
49	const static uint64_t TILING_KEY_GENERALIZED = 0;
50	const static uint64_t TILING_KEY_INFER = 1; // 推理路径 TilingKey（DataCopyPad方式）
51	const static uint64_t NUM_0 = 0;
52	const static uint64_t NUM_8 = 8;
53	const static uint64_t DIM_NUM_0 = 0;
54	const static uint64_t DIM_NUM_1 = 1;
55	const static uint64_t DIM_NUM_2 = 2;
56	const static uint64_t DIM_NUM_3 = 3;
57	const static uint64_t DIM_NUM_4 = 4;
58	const static int64_t DIM_NUM_LAST = -1;
59	const static uint64_t MAX_N_NUM_FLAG1 = 12;
60	const static uint64_t MAX_N_NUM_FLAG0 = 8; // 推理路径 n ≤ ALIGN_N=8
61	const static uint64_t MAX_UB_LIMIT = 190 * 1024;
62	const static uint64_t BIT_WIDTH_32 = 32;
63	const static uint64_t MIN_PER_CORE_ELEMENTS = 32;
64	const static uint64_t MIN_PER_CORE_ELEMENTS_INFER = 8; // 推理路径：允许更细粒度分核，使更多核参与运算
65	const static uint64_t INFER_MAX_TILE_ELEMENTS = 32; // 推理路径：限制每次循环最多处理 32 个 t，强制多循环以利用双缓冲
66	const static uint64_t ALIGN_N_HOST = 8; // 推理 UB 公式用（DataCopyPad pad 到 8）
67	
68	// Input/Output indices
69	const static int64_t X_INPUT_INDEX = 0;
70	const static int64_t OUTPUT_OUTPUT_INDEX = 0;
71	const static int64_t NORM_OUT_OUTPUT_INDEX = 1;
72	const static int64_t SUM_OUT_OUTPUT_INDEX = 2;
73	
74	// Attribute indices
75	const static int64_t OUT_FLAG_ATTR_INDEX = 0;
76	const static int64_t EPS_ATTR_INDEX = 1;
77	const static int64_t NUM_ITERS_ATTR_INDEX = 2;
78	
79	class SinkhornTilingBase : public Ops::Transformer::OpTiling::TilingBase {
80	public:
81	    explicit SinkhornTilingBase(gert::TilingContext *context)
82	        : Ops::Transformer::OpTiling::TilingBase(context)
