89	    {
90	        TilingBase::Reset(context);
91	        Reset();
92	    }
93	
94	  protected:
95	    bool IsCapable() override
96	    {
97	        return true;
98	    }
99	
100	    // 1、获取平台信息比如CoreNum、UB/L1/L0C资源大小
101	    ge::graphStatus GetPlatformInfo() override;
102	    // 2、获取INPUT/OUTPUT/ATTR信息
103	    ge::graphStatus GetShapeAttrsInfo() override;
104	    // 3、计算数据切分TilingData
105	    ge::graphStatus DoOpTiling() override;
106	    // 4、计算高阶API的TilingData
107	    ge::graphStatus DoLibApiTiling() override;
108	    // 5、计算TilingKey
