110	    // 6、计算Workspace 大小
111	    ge::graphStatus GetWorkspaceSize() override;
112	    // 7、保存Tiling数据
113	    ge::graphStatus PostTiling() override;
114	    void Reset();
115	
116	  private:
117	    ge::graphStatus CheckInputShape();
118	    ge::graphStatus CheckOutputShape();
119	    ge::graphStatus CheckOptionalOutputShape();
120	    ge::graphStatus SplitCores();
121	    uint64_t CalTAlign();
122	    const gert::Shape *xShape_ = nullptr;
123	    const gert::Shape *outputShape_ = nullptr;
124	    const gert::Shape *normOutShape_ = nullptr;
125	    const gert::Shape *sumOutShape_ = nullptr;
126	
127	    int64_t totalLength_ = 0;
128	    int64_t tAlign_ = 0;
129	    int64_t TNum_ = 0;
130	    int64_t BNum_ = 0;
131	    int64_t SNum_ = 0;
132	    int64_t nNum_ = 0;
133	    int64_t dimNum_ = 0;
134	    int64_t outFlag_ = 0;
135	    float eps_ = 1e-6F;
136	    int64_t numIters_ = 20;
137	    bool isTShape_ = false;
138	    int64_t inputDtypeSize_ = 4;
