142	
143	ge::graphStatus SinkhornTilingBase::GetPlatformInfo()
144	{
145	    auto platformInfo = context_->GetPlatformInfo();
146	    OP_CHECK_IF(platformInfo == nullptr, OP_LOGE(context_, "fail to get platform info"), return ge::GRAPH_FAILED);
147	
148	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
149	    aicoreParams_.blockDim = ascendcPlatform.GetCoreNumAiv();
150	    uint64_t ubSizePlatForm;
151	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizePlatForm);
152	    aicoreParams_.ubSize = ubSizePlatForm;
153	
154	    return ge::GRAPH_SUCCESS;
155	}
156	
157	ge::graphStatus SinkhornTilingBase::GetShapeAttrsInfo()
158	{
159	    opName_ = context_->GetNodeName();
160	
161	    // 获取输入shape信息
162	    auto xShapePtr = context_->GetInputShape(X_INPUT_INDEX);
163	    OP_CHECK_NULL_WITH_CONTEXT(context_, xShapePtr);
164	    xShape_ = &xShapePtr->GetStorageShape();
165	
166	    // 验证数据类型
167	    auto xDesc = context_->GetInputDesc(X_INPUT_INDEX);
168	    OP_CHECK_NULL_WITH_CONTEXT(context_, xDesc);
169	    auto xDtype = xDesc->GetDataType();
170	    OP_CHECK_IF((xDtype != ge::DataType::DT_FLOAT),
171	                OP_LOGE(context_,
172	                        "x dtype %s error, only supports float32. please check.",
173	                        ge::TypeUtils::DataTypeToSerialString(xDtype).c_str()),
174	                return ge::GRAPH_FAILED);
175	
176	    // 获取属性
177	    auto attrs = context_->GetAttrs();
178	    OP_CHECK_NULL_WITH_CONTEXT(context_, attrs);
179	
180	    const int64_t *outFlagPtr = attrs->GetAttrPointer<int64_t>(OUT_FLAG_ATTR_INDEX);
181	    if (outFlagPtr != nullptr) {
182	        outFlag_ = *outFlagPtr;
183	        OP_CHECK_IF(outFlag_ != 0 && outFlag_ != 1,
184	                    OP_LOGE(context_, "outFlag_ should be 0 or 1, but got %ld", outFlag_),
185	                    return ge::GRAPH_FAILED);
186	
187	        tilingData_.set_outFlag(outFlag_);
188	    }
189	    OP_LOGI(context_, "Attr out_flag is: %ld ", outFlag_);
190	
191	    const float *epsPtr = attrs->GetAttrPointer<float>(EPS_ATTR_INDEX);
192	    if (epsPtr != nullptr) {
193	        eps_ = *epsPtr;
194	        OP_CHECK_IF(
195	            eps_ <= 0.0F, OP_LOGE(context_, "eps_ should be bigger than 0, but got %f", eps_), return ge::GRAPH_FAILED);
196	        tilingData_.set_eps(eps_);
197	    }
198	    OP_LOGI(context_, "Attr eps is: %f ", eps_);
199	    const int64_t *numItersPtr = attrs->GetAttrPointer<int64_t>(NUM_ITERS_ATTR_INDEX);
200	    if (numItersPtr != nullptr) {
201	        numIters_ = *numItersPtr;
202	        OP_CHECK_IF(numIters_ < 1 || numIters_ > 100,
203	                    OP_LOGE(context_, "numIters_ should be [1,100], but got %ld", numIters_),
204	                    return ge::GRAPH_FAILED);
205	        tilingData_.set_numIters(numIters_);
206	    }
207	    OP_LOGI(context_, "Attr num_iters is: %ld ", numIters_);
208	
209	    inputDtypeSize_ = static_cast<int64_t>(ge::GetSizeByDataType(xDtype));
210	
211	    // 获取输出shape
212	    auto outputShapePtr = context_->GetOutputShape(OUTPUT_OUTPUT_INDEX);
213	    OP_CHECK_NULL_WITH_CONTEXT(context_, outputShapePtr);
214	    outputShape_ = &outputShapePtr->GetStorageShape();
215	
216	    if (outFlag_ == 1) {
217	        auto normOutShapePtr = context_->GetOutputShape(NORM_OUT_OUTPUT_INDEX);
218	        OP_CHECK_NULL_WITH_CONTEXT(context_, normOutShapePtr);
219	        normOutShape_ = &normOutShapePtr->GetStorageShape();
220	
221	        auto sumOutShapePtr = context_->GetOutputShape(SUM_OUT_OUTPUT_INDEX);
222	        OP_CHECK_NULL_WITH_CONTEXT(context_, sumOutShapePtr);
223	        sumOutShape_ = &sumOutShapePtr->GetStorageShape();
224	    }
225	
226	    return ge::GRAPH_SUCCESS;
227	}
228	
229	uint64_t SinkhornTilingBase::CalTAlign()
230	{
231	    if (nNum_ <= NUM_0) {
232	        return -1;
233	    }
234	
235	    uint64_t denominator = 0;
236	    if (outFlag_ == 1) {
237	        // (5*t*n² +4*t*n)*inputDtypeSize_ + 1024*n*n< 190k  → t < 190k -1024*n*n/ ((5*n² + 16*n) * inputDtypeSize_)
238	        denominator = (5 * nNum_ * nNum_ + 4 * nNum_) * inputDtypeSize_;
239	    } else {
240	        // 推理路径：6 个 buffer 槽 (xInQueue×2 + outputQueue×2 + sumBuf + tmpBuf)
241	        // UB = 6 * t * n * ALIGN_N * sizeof(T)，无 Transpose 额外开销
242	        denominator = 6 * ALIGN_N_HOST * nNum_ * inputDtypeSize_;
243	    }
244	    uint64_t max_t_theory;
245	    if (outFlag_ == 1) {
246	        max_t_theory = (MAX_UB_LIMIT - (2 * nNum_ * nNum_ + 1) * 512) / denominator; // 理论最大合规t值
247	    } else {
248	        max_t_theory = MAX_UB_LIMIT / denominator; // 推理路径无 Transpose 开销
249	        max_t_theory = std::min(max_t_theory, INFER_MAX_TILE_ELEMENTS);
250	    }
251	
252	    // 32位对齐取整
253	    uint64_t t_align = AlignDown(max_t_theory, BIT_WIDTH_32 / inputDtypeSize_);
254	
255	    return t_align;
256	}
257	
258	ge::graphStatus SinkhornTilingBase::CheckInputShape()
259	{
260	    OP_CHECK_IF(xShape_ == nullptr, OP_LOGE(context_, "x shape is null"), return ge::GRAPH_FAILED);
261	
262	    dimNum_ = xShape_->GetDimNum();
263	    if (dimNum_ == DIM_NUM_3) { // Tnn
264	        isTShape_ = true;
265	        TNum_ = xShape_->GetDim(DIM_NUM_0);
266	        OP_CHECK_IF(
267	            TNum_ <= NUM_0, OP_LOGE(context_, "T should be positive, but got %ld", TNum_), return ge::GRAPH_FAILED);
268	        totalLength_ = TNum_;
269	        nNum_ = xShape_->GetDim(DIM_NUM_1);
270	        OP_CHECK_IF(xShape_->GetDim(dimNum_ - 1) != nNum_,
271	                    OP_LOGE(context_, "n should be the same, but got %u and %ld", nNum_, xShape_->GetDim(DIM_NUM_LAST)),
272	                    return ge::GRAPH_FAILED);
273	    } else if (dimNum_ == DIM_NUM_4) { // BSnn
274	        isTShape_ = false;
275	
276	        BNum_ = xShape_->GetDim(DIM_NUM_0);
277	        SNum_ = xShape_->GetDim(DIM_NUM_1);
278	        totalLength_ = BNum_ * SNum_;
279	        OP_CHECK_IF(
280	            BNum_ <= NUM_0, OP_LOGE(context_, "B should be positive, but got %ld", BNum_), return ge::GRAPH_FAILED);
281	        OP_CHECK_IF(
282	            SNum_ <= NUM_0, OP_LOGE(context_, "S should be positive, but got %ld", SNum_), return ge::GRAPH_FAILED);
283	        nNum_ = xShape_->GetDim(DIM_NUM_2);
284	        OP_CHECK_IF(xShape_->GetDim(dimNum_ - 1) != nNum_,
285	                    OP_LOGE(context_, "n should be the same, but got %u and %ld", nNum_, xShape_->GetDim(DIM_NUM_LAST)),
286	                    return ge::GRAPH_FAILED);
287	    } else {
288	        OP_LOGE(context_, "x dim should be 3 or 4, but got %u", dimNum_);
289	        return ge::GRAPH_FAILED;
290	    }
291	
292	    OP_CHECK_IF(totalLength_ <= NUM_0,
293	                OP_LOGE(context_, "totalLength_ should be positive , but got %u", totalLength_),
294	                return ge::GRAPH_FAILED);
295	    tilingData_.set_totalLength(totalLength_);
296	
297	    // UB内存限制： (5t*n*n + 4t*n ) *  inputDtypeSize + 1024*n*n < ubSize或者(3t*n*n + 2t*n ) *  inputDtypeSize +
298	    // 1024*n*n < ubSize
299	    //（考虑ubSize预留一定空间，按照190KB计算）
300	    // 考虑32位对齐，t最小为8
301	    if (outFlag_ == 1) {
302	        OP_CHECK_IF(nNum_ > MAX_N_NUM_FLAG1 || nNum_ <= NUM_0,
303	                    OP_LOGE(context_, "n should not bigger than 12 and should be positive , but got %u", nNum_),
304	                    return ge::GRAPH_FAILED);
305	    } else {
306	        // 推理路径（out_flag=0）：n 受 ALIGN_N=8 限制（DataCopyPad 仅能 pad 到 ALIGN_N）
307	        OP_CHECK_IF(nNum_ > MAX_N_NUM_FLAG0 || nNum_ <= NUM_0,
308	                    OP_LOGE(context_, "n should not bigger than 8 and should be positive , but got %u", nNum_),
309	                    return ge::GRAPH_FAILED);
310	    }
311	
312	    tilingData_.set_nNum(nNum_);
313	    OP_LOGI(context_, "nNum_ is: %ld, total_length is: %ld", nNum_, totalLength_);
314	
315	    return ge::GRAPH_SUCCESS;
316	}
317	
318	ge::graphStatus SinkhornTilingBase::CheckOutputShape()
319	{
320	    OP_CHECK_IF(outputShape_ == nullptr, OP_LOGE(context_, "output shape is null"), return ge::GRAPH_FAILED);
321	
322	    size_t xDimNum = xShape_->GetDimNum();
323	    size_t outputDimNum = outputShape_->GetDimNum();
324	    OP_CHECK_IF(outputDimNum != xDimNum,
325	                OP_LOGE(context_, "outputDimNum should be the same as the xDimNum, but got %u", outputDimNum),
326	                return ge::GRAPH_FAILED);
327	
328	    if (isTShape_) {
329	        OP_CHECK_IF(outputShape_->GetDim(DIM_NUM_0) != TNum_ || outputShape_->GetDim(DIM_NUM_1) != nNum_ ||
330	                        outputShape_->GetDim(DIM_NUM_2) != nNum_,
331	                    OP_LOGE(context_,
332	                            "outputShape_ should be [%u,%u,%u], but got [%d,%d,%d].",
333	                            TNum_,
334	                            nNum_,
335	                            nNum_,
336	                            outputShape_->GetDim(DIM_NUM_0),
337	                            outputShape_->GetDim(DIM_NUM_1),
338	                            outputShape_->GetDim(DIM_NUM_2)),
339	                    return ge::GRAPH_FAILED);
340	    } else {
341	        OP_CHECK_IF(outputShape_->GetDim(DIM_NUM_0) != BNum_ || outputShape_->GetDim(DIM_NUM_1) != SNum_ ||
342	                        outputShape_->GetDim(DIM_NUM_2) != nNum_ || outputShape_->GetDim(DIM_NUM_3) != nNum_,
343	                    OP_LOGE(context_,
344	                            "outputShape_ should be [%u,%u,%u,%u], but got [%d,%d,%d,%d].",
345	                            BNum_,
346	                            SNum_,
347	                            nNum_,
348	                            nNum_,
349	                            outputShape_->GetDim(DIM_NUM_0),
350	                            outputShape_->GetDim(DIM_NUM_1),
351	                            outputShape_->GetDim(DIM_NUM_2),
352	                            outputShape_->GetDim(DIM_NUM_3)),
353	                    return ge::GRAPH_FAILED);
354	    }
355	
356	    return ge::GRAPH_SUCCESS;
357	}
358	
359	ge::graphStatus SinkhornTilingBase::CheckOptionalOutputShape()
360	{
361	    // 检验dim值
362	    OP_CHECK_IF(normOutShape_ == nullptr, OP_LOGE(context_, "normOut shape is null"), return ge::GRAPH_FAILED);
363	
364	    size_t normOutDimNum = normOutShape_->GetDimNum();
365	    OP_CHECK_IF(normOutDimNum != dimNum_ + 1,
366	                OP_LOGE(context_, "normOutDimNum should be the same as %d, but got %d", dimNum_ + 1, normOutDimNum),
367	                return ge::GRAPH_FAILED);
368	
369	    OP_CHECK_IF(sumOutShape_ == nullptr, OP_LOGE(context_, "normOut shape is null"), return ge::GRAPH_FAILED);
370	
371	    size_t sumOutDimNum = sumOutShape_->GetDimNum();
372	    OP_CHECK_IF(sumOutDimNum != dimNum_,
373	                OP_LOGE(context_, "sumOutDimNum should be the same as %d, but got %d", dimNum_, sumOutDimNum),
374	                return ge::GRAPH_FAILED);
375	
376	    if (isTShape_) {
377	        OP_CHECK_IF(normOutShape_->GetDim(DIM_NUM_0) != 2 * numIters_ || normOutShape_->GetDim(DIM_NUM_1) != nNum_ ||
378	                        normOutShape_->GetDim(DIM_NUM_2) != nNum_ || normOutShape_->GetDim(DIM_NUM_3) != TNum_,
379	                    OP_LOGE(context_,
380	                            "normOutShape_ should be [%u,%u,%u,%u], but got [%d,%d,%d,%d].",
381	                            2 * numIters_,
382	                            nNum_,
383	                            nNum_,
384	                            TNum_,
385	                            normOutShape_->GetDim(DIM_NUM_0),
386	                            normOutShape_->GetDim(DIM_NUM_1),
387	                            normOutShape_->GetDim(DIM_NUM_2),
388	                            normOutShape_->GetDim(DIM_NUM_3)),
389	                    return ge::GRAPH_FAILED);
390	
391	        OP_CHECK_IF(sumOutShape_->GetDim(DIM_NUM_0) != 2 * numIters_ || sumOutShape_->GetDim(DIM_NUM_1) != nNum_ ||
392	                        sumOutShape_->GetDim(DIM_NUM_2) != TNum_,
393	                    OP_LOGE(context_,
394	                            "sumOutShape_ should be [%u,%u,%u], but got [%d,%d,%d].",
395	                            2 * numIters_,
396	                            nNum_,
397	                            TNum_,
398	                            normOutShape_->GetDim(DIM_NUM_0),
399	                            normOutShape_->GetDim(DIM_NUM_1),
400	                            normOutShape_->GetDim(DIM_NUM_2)),
401	                    return ge::GRAPH_FAILED);
402	    } else {
403	        OP_CHECK_IF(normOutShape_->GetDim(DIM_NUM_0) != 2 * numIters_ || normOutShape_->GetDim(DIM_NUM_1) != nNum_ ||
404	                        normOutShape_->GetDim(DIM_NUM_2) != nNum_ || normOutShape_->GetDim(DIM_NUM_3) != BNum_ ||
405	                        normOutShape_->GetDim(DIM_NUM_4) != SNum_,
406	                    OP_LOGE(context_,
407	                            "normOutShape_ should be [%u,%u,%u,%u,%u], but got [%d,%d,%d,%d,%d].",
408	                            2 * numIters_,
409	                            nNum_,
410	                            nNum_,
411	                            BNum_,
412	                            SNum_,
413	                            normOutShape_->GetDim(DIM_NUM_0),
414	                            normOutShape_->GetDim(DIM_NUM_1),
415	                            normOutShape_->GetDim(DIM_NUM_2),
416	                            normOutShape_->GetDim(DIM_NUM_3),
417	                            normOutShape_->GetDim(DIM_NUM_4)),
418	                    return ge::GRAPH_FAILED);
419	
420	        OP_CHECK_IF(sumOutShape_->GetDim(DIM_NUM_0) != 2 * numIters_ || sumOutShape_->GetDim(DIM_NUM_1) != nNum_ ||
421	                        sumOutShape_->GetDim(DIM_NUM_2) != BNum_ || sumOutShape_->GetDim(DIM_NUM_3) != SNum_,
422	                    OP_LOGE(context_,
423	                            "sumOutShape_ should be [%u,%u,%u,%u], but got [%d,%d,%d,%d].",
424	                            2 * numIters_,
425	                            nNum_,
426	                            BNum_,
427	                            SNum_,
428	                            normOutShape_->GetDim(DIM_NUM_0),
429	                            normOutShape_->GetDim(DIM_NUM_1),
430	                            normOutShape_->GetDim(DIM_NUM_2),
431	                            sumOutShape_->GetDim(DIM_NUM_3)),
432	                    return ge::GRAPH_FAILED);
433	    }
434	    return ge::GRAPH_SUCCESS;
435	}
436	
437	ge::graphStatus SinkhornTilingBase::SplitCores()
438	{
439	    // 核间切分：在数据维度上进行核间切分 每个核处理的t数量尽量均匀
440	    int64_t aivNum = static_cast<int64_t>(aicoreParams_.blockDim);
441	    int64_t perCoreElements = CeilDiv(totalLength_, aivNum);
442	
443	    // 限核：推理路径（out_flag=0）允许更细粒度分核（MIN=8），提高小T场景并行度
444	    //       训练路径（out_flag=1）保持原有限制（MIN=32）
445	    int64_t minPerCore = static_cast<int64_t>((outFlag_ == 0) ? MIN_PER_CORE_ELEMENTS_INFER : MIN_PER_CORE_ELEMENTS);
446	    if (perCoreElements < minPerCore && totalLength_ >= minPerCore) {
447	        perCoreElements = minPerCore;
448	    } else if (outFlag_ == 1) {
449	        // 训练路径：对齐到 8 元素边界
450	        perCoreElements = AlignUp(perCoreElements, BIT_WIDTH_32 / inputDtypeSize_);
451	    }
452	    // 推理路径（outFlag_==0）：不做 AlignUp，直接用 CeilDiv 结果，避免越界
453	    int64_t needCoreNum = CeilDiv(totalLength_, perCoreElements);
454	    int64_t lastCoreElements = totalLength_ - perCoreElements * (needCoreNum - 1);
455	
456	    tilingData_.set_needCoreNum(needCoreNum);
457	    tilingData_.set_perCoreElements(perCoreElements);
458	    tilingData_.set_lastCoreElements(lastCoreElements);
459	
460	    OP_LOGI(context_,
461	            "Core splitting: needCoreNum=%ld, perCoreElements=%ld, lastCoreElements=%ld",
462	            needCoreNum,
463	            perCoreElements,
464	            lastCoreElements);
465	
466	    tAlign_ = CalTAlign();
467	    OP_CHECK_IF(tAlign_ <= NUM_0,
468	                OP_LOGE(context_, "tAlign_ should be positive , but got %u", tAlign_),
469	                return ge::GRAPH_FAILED);
470	
471	    // 核内切分：头核 perCorePerLoopElements天然32位对齐
472	    int64_t perCorePerLoopElements = std::min(perCoreElements, tAlign_);
473	    int64_t perCoreLoops = CeilDiv(perCoreElements, perCorePerLoopElements);
474	    int64_t perCoreLastLoopElements = perCoreElements - perCorePerLoopElements * (perCoreLoops - 1);
475	
476	    // 核内切分：尾核
477	    int64_t lastCorePerLoopElements = std::min(lastCoreElements, tAlign_);
478	    int64_t lastCoreLoops = CeilDiv(lastCoreElements, lastCorePerLoopElements);
479	    int64_t lastCoreLastLoopElements = lastCoreElements - lastCorePerLoopElements * (lastCoreLoops - 1);
480	
481	    tilingData_.set_perCorePerLoopElements(perCorePerLoopElements);
482	    tilingData_.set_perCoreLoops(perCoreLoops);
483	    tilingData_.set_perCoreLastLoopElements(perCoreLastLoopElements);
484	    tilingData_.set_lastCorePerLoopElements(lastCorePerLoopElements);
485	    tilingData_.set_lastCoreLoops(lastCoreLoops);
486	    tilingData_.set_lastCoreLastLoopElements(lastCoreLastLoopElements);
487	
488	    return ge::GRAPH_SUCCESS;
489	}
490	
491	ge::graphStatus SinkhornTilingBase::DoOpTiling()
492	{
493	    auto ret = CheckInputShape();
494	    if (ret != ge::GRAPH_SUCCESS) {
495	        return ret;
496	    }
497	
498	    ret = CheckOutputShape();
499	    if (ret != ge::GRAPH_SUCCESS) {
500	        return ret;
501	    }
502	
503	    if (outFlag_ == 1) {
504	        ret = CheckOptionalOutputShape();
505	        if (ret != ge::GRAPH_SUCCESS) {
506	            return ret;
507	        }
508	    }
509	
510	    ret = SplitCores();
511	    if (ret != ge::GRAPH_SUCCESS) {
512	        return ret;
513	    }
514	
515	    // 预计算 reduceMask（仅推理路径 out_flag=0 使用）
516	    // 动态 mask：低 n_ 位有效，重复 8 次填满 64bit
517	    // e.g. n=4: 0x0F → 0x0F0F0F0F0F0F0F0F
518	    //      n=8: 0xFF → 0xFFFFFFFFFFFFFFFF
519	    if (outFlag_ == 0) {
520	        uint64_t rowBits = (nNum_ < 64) ? ((1ULL << nNum_) - 1ULL) : ~0ULL;
521	        uint64_t fullMask = 0;
522	        for (uint64_t i = 0; i < 8; ++i) {
523	            fullMask |= (rowBits << (i * 8));
524	        }
525	        tilingData_.set_reduceMask(fullMask);
526	    } else {
527	        // 训练路径不使用，设为 0
528	        tilingData_.set_reduceMask(0);
529	    }
530	
531	    return ge::GRAPH_SUCCESS;
532	}
533	
534	ge::graphStatus SinkhornTilingBase::DoLibApiTiling()
535	{
536	    return ge::GRAPH_SUCCESS;
537	}
538	
539	ge::graphStatus SinkhornTilingBase::GetWorkspaceSize()
540	{
541	    // 计算 workspace 大小
542	    workspaceSize_ = DEFAULT_WORKSPACE_SIZE;
543	    return ge::GRAPH_SUCCESS;
544	}
545	
546	ge::graphStatus SinkhornTilingBase::PostTiling()
547	{
548	    context_->SetBlockDim(tilingData_.get_needCoreNum());
549	    size_t *currentWorkspace = context_->GetWorkspaceSizes(1);
550	    currentWorkspace[0] = workspaceSize_;
551	    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
552	    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
553	    return ge::GRAPH_SUCCESS;
554	}
555	
556	uint64_t SinkhornTilingBase::GetTilingKey() const
557	{
558	    // out_flag=0 → 推理路径（DataCopyPad 模板）
559	    // out_flag=1 → 训练路径（Transpose 模板，保持原有行为）
560	    return (outFlag_ == 0) ? TILING_KEY_INFER : TILING_KEY_GENERALIZED;
561	}
562	
563	void SinkhornTilingBase::Reset()
564	{
565	    opName_ = nullptr;
566	    totalLength_ = 0;
567	    tAlign_ = 0;
568	    outFlag_ = 0;
569	    eps_ = 1e-6F;
570	    numIters_ = 20;
571	    inputDtypeSize_ = 4;
572	    nNum_ = 0;
573	    TNum_ = 0;
574	    BNum_ = 0;
575	    SNum_ = 0;
576	    isTShape_ = false;
577	    return;
578	}
579	
