/*!
 * \file manifold_constrained_hyper_connection_sinkhorn_enhance_tiling.cpp
 * \brief
 */
#include <cmath>
#include "register/op_def_registry.h"
#include "tiling_base/tiling_templates_registry.h"
#include "tiling_base/tiling_base.h"
#include "platform/platform_info.h"
#include "log/log.h"
#include "manifold_constrained_hyper_connection_sinkhorn_enhance_tiling.h"
namespace optiling {
// Helper function for ceiling division
inline int64_t CeilDiv(int64_t a, int64_t b)
{
    if (b == 0) {
        return 0;
    }
    return (a + b - 1) / b;
}

inline int64_t AlignDown(int64_t a, int64_t b)
{
    if (b == 0) {
        return 0;
    }
    return a / b * b;
}

inline int64_t AlignUp(int64_t a, int64_t b)
{
    if (b == 0) {
        return 0;
    }
    return CeilDiv(a, b) * b;
}
// Constants
const static int64_t DEFAULT_WORKSPACE_SIZE = 16777216; // 16M预留空间
const static uint64_t TILING_KEY_GENERALIZED = 0;
const static uint64_t TILING_KEY_INFER = 1; // 推理路径 TilingKey（DataCopyPad方式）
const static uint64_t NUM_0 = 0;
const static uint64_t NUM_8 = 8;
const static uint64_t DIM_NUM_0 = 0;
const static uint64_t DIM_NUM_1 = 1;
const static uint64_t DIM_NUM_2 = 2;
const static uint64_t DIM_NUM_3 = 3;
const static uint64_t DIM_NUM_4 = 4;
const static int64_t DIM_NUM_LAST = -1;
const static uint64_t MAX_N_NUM_FLAG1 = 12;
const static uint64_t MAX_N_NUM_FLAG0 = 8; // 推理路径 n ≤ ALIGN_N=8
const static uint64_t MAX_UB_LIMIT = 190 * 1024;
const static uint64_t BIT_WIDTH_32 = 32;
const static uint64_t MIN_PER_CORE_ELEMENTS = 32;
const static uint64_t MIN_PER_CORE_ELEMENTS_INFER = 8; // 推理路径：允许更细粒度分核，使更多核参与运算
const static uint64_t INFER_MAX_TILE_ELEMENTS = 32; // 推理路径：限制每次循环最多处理 32 个 t，强制多循环以利用双缓冲
const static uint64_t ALIGN_N_HOST = 8; // 推理 UB 公式用（DataCopyPad pad 到 8）

// Input/Output indices
const static int64_t X_INPUT_INDEX = 0;
const static int64_t OUTPUT_OUTPUT_INDEX = 0;
const static int64_t NORM_OUT_OUTPUT_INDEX = 1;
const static int64_t SUM_OUT_OUTPUT_INDEX = 2;

// Attribute indices
const static int64_t OUT_FLAG_ATTR_INDEX = 0;
const static int64_t EPS_ATTR_INDEX = 1;
const static int64_t NUM_ITERS_ATTR_INDEX = 2;

class SinkhornTilingBase : public Ops::Transformer::OpTiling::TilingBase {
public:
    explicit SinkhornTilingBase(gert::TilingContext *context)
        : Ops::Transformer::OpTiling::TilingBase(context)
    {
        Reset();
    }
    ~SinkhornTilingBase() override = default;

    void Reset(gert::TilingContext *context) override
    {
        TilingBase::Reset(context);
        Reset();
    }

  protected:
    bool IsCapable() override
    {
        return true;
    }

    // 1、获取平台信息比如CoreNum、UB/L1/L0C资源大小
    ge::graphStatus GetPlatformInfo() override;
    // 2、获取INPUT/OUTPUT/ATTR信息
    ge::graphStatus GetShapeAttrsInfo() override;
    // 3、计算数据切分TilingData
    ge::graphStatus DoOpTiling() override;
    // 4、计算高阶API的TilingData
    ge::graphStatus DoLibApiTiling() override;
    // 5、计算TilingKey
    uint64_t GetTilingKey() const override;
    // 6、计算Workspace 大小
    ge::graphStatus GetWorkspaceSize() override;
    // 7、保存Tiling数据
    ge::graphStatus PostTiling() override;
    void Reset();

  private:
    ge::graphStatus CheckInputShape();
    ge::graphStatus CheckOutputShape();
    ge::graphStatus CheckOptionalOutputShape();
    ge::graphStatus SplitCores();
    uint64_t CalTAlign();
    const gert::Shape *xShape_ = nullptr;
    const gert::Shape *outputShape_ = nullptr;
    const gert::Shape *normOutShape_ = nullptr;
    const gert::Shape *sumOutShape_ = nullptr;

    int64_t totalLength_ = 0;
    int64_t tAlign_ = 0;
    int64_t TNum_ = 0;
    int64_t BNum_ = 0;
    int64_t SNum_ = 0;
    int64_t nNum_ = 0;
    int64_t dimNum_ = 0;
    int64_t outFlag_ = 0;
    float eps_ = 1e-6F;
    int64_t numIters_ = 20;
    bool isTShape_ = false;
    int64_t inputDtypeSize_ = 4;
    const char *opName_ = "";
    SinkhornTilingData tilingData_;
};

ge::graphStatus SinkhornTilingBase::GetPlatformInfo()
{
    auto platformInfo = context_->GetPlatformInfo();
    OP_CHECK_IF(platformInfo == nullptr, OP_LOGE(context_, "fail to get platform info"), return ge::GRAPH_FAILED);

    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
    aicoreParams_.blockDim = ascendcPlatform.GetCoreNumAiv();
    uint64_t ubSizePlatForm;
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizePlatForm);
    aicoreParams_.ubSize = ubSizePlatForm;

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus SinkhornTilingBase::GetShapeAttrsInfo()
{
    opName_ = context_->GetNodeName();

    // 获取输入shape信息
    auto xShapePtr = context_->GetInputShape(X_INPUT_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context_, xShapePtr);
    xShape_ = &xShapePtr->GetStorageShape();

    // 验证数据类型
    auto xDesc = context_->GetInputDesc(X_INPUT_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context_, xDesc);
    auto xDtype = xDesc->GetDataType();
    OP_CHECK_IF((xDtype != ge::DataType::DT_FLOAT),
                OP_LOGE(context_,
                        "x dtype %s error, only supports float32. please check.",
                        ge::TypeUtils::DataTypeToSerialString(xDtype).c_str()),
                return ge::GRAPH_FAILED);

    // 获取属性
    auto attrs = context_->GetAttrs();
    OP_CHECK_NULL_WITH_CONTEXT(context_, attrs);

    const int64_t *outFlagPtr = attrs->GetAttrPointer<int64_t>(OUT_FLAG_ATTR_INDEX);
    if (outFlagPtr != nullptr) {
        outFlag_ = *outFlagPtr;
        OP_CHECK_IF(outFlag_ != 0 && outFlag_ != 1,
                    OP_LOGE(context_, "outFlag_ should be 0 or 1, but got %ld", outFlag_),
                    return ge::GRAPH_FAILED);

        tilingData_.set_outFlag(outFlag_);
    }
    OP_LOGI(context_, "Attr out_flag is: %ld ", outFlag_);

    const float *epsPtr = attrs->GetAttrPointer<float>(EPS_ATTR_INDEX);
    if (epsPtr != nullptr) {
        eps_ = *epsPtr;
        OP_CHECK_IF(
            eps_ <= 0.0F, OP_LOGE(context_, "eps_ should be bigger than 0, but got %f", eps_), return ge::GRAPH_FAILED);
        tilingData_.set_eps(eps_);
    }
    OP_LOGI(context_, "Attr eps is: %f ", eps_);
    const int64_t *numItersPtr = attrs->GetAttrPointer<int64_t>(NUM_ITERS_ATTR_INDEX);
    if (numItersPtr != nullptr) {
        numIters_ = *numItersPtr;
        OP_CHECK_IF(numIters_ < 1 || numIters_ > 100,
                    OP_LOGE(context_, "numIters_ should be [1,100], but got %ld", numIters_),
                    return ge::GRAPH_FAILED);
        tilingData_.set_numIters(numIters_);
    }
    OP_LOGI(context_, "Attr num_iters is: %ld ", numIters_);

    inputDtypeSize_ = static_cast<int64_t>(ge::GetSizeByDataType(xDtype));

    // 获取输出shape
    auto outputShapePtr = context_->GetOutputShape(OUTPUT_OUTPUT_INDEX);
    OP_CHECK_NULL_WITH_CONTEXT(context_, outputShapePtr);
    outputShape_ = &outputShapePtr->GetStorageShape();

    if (outFlag_ == 1) {
        auto normOutShapePtr = context_->GetOutputShape(NORM_OUT_OUTPUT_INDEX);
        OP_CHECK_NULL_WITH_CONTEXT(context_, normOutShapePtr);
        normOutShape_ = &normOutShapePtr->GetStorageShape();

        auto sumOutShapePtr = context_->GetOutputShape(SUM_OUT_OUTPUT_INDEX);
        OP_CHECK_NULL_WITH_CONTEXT(context_, sumOutShapePtr);
        sumOutShape_ = &sumOutShapePtr->GetStorageShape();
    }

    return ge::GRAPH_SUCCESS;
}

uint64_t SinkhornTilingBase::CalTAlign()
{
    if (nNum_ <= NUM_0) {
        return -1;
    }

    uint64_t denominator = 0;
    if (outFlag_ == 1) {
        // (5*t*n² +4*t*n)*inputDtypeSize_ + 1024*n*n< 190k  → t < 190k -1024*n*n/ ((5*n² + 16*n) * inputDtypeSize_)
        denominator = (5 * nNum_ * nNum_ + 4 * nNum_) * inputDtypeSize_;
    } else {
        // 推理路径：6 个 buffer 槽 (xInQueue×2 + outputQueue×2 + sumBuf + tmpBuf)
        // UB = 6 * t * n * ALIGN_N * sizeof(T)，无 Transpose 额外开销
        denominator = 6 * ALIGN_N_HOST * nNum_ * inputDtypeSize_;
    }
    uint64_t max_t_theory;
    if (outFlag_ == 1) {
        max_t_theory = (MAX_UB_LIMIT - (2 * nNum_ * nNum_ + 1) * 512) / denominator; // 理论最大合规t值
    } else {
        max_t_theory = MAX_UB_LIMIT / denominator; // 推理路径无 Transpose 开销
        max_t_theory = std::min(max_t_theory, INFER_MAX_TILE_ELEMENTS);
    }

    // 32位对齐取整
    uint64_t t_align = AlignDown(max_t_theory, BIT_WIDTH_32 / inputDtypeSize_);

    return t_align;
}

ge::graphStatus SinkhornTilingBase::CheckInputShape()
{
    OP_CHECK_IF(xShape_ == nullptr, OP_LOGE(context_, "x shape is null"), return ge::GRAPH_FAILED);

    dimNum_ = xShape_->GetDimNum();
    if (dimNum_ == DIM_NUM_3) { // Tnn
        isTShape_ = true;
        TNum_ = xShape_->GetDim(DIM_NUM_0);
        OP_CHECK_IF(
            TNum_ <= NUM_0, OP_LOGE(context_, "T should be positive, but got %ld", TNum_), return ge::GRAPH_FAILED);
        totalLength_ = TNum_;
        nNum_ = xShape_->GetDim(DIM_NUM_1);
        OP_CHECK_IF(xShape_->GetDim(dimNum_ - 1) != nNum_,
                    OP_LOGE(context_, "n should be the same, but got %u and %ld", nNum_, xShape_->GetDim(DIM_NUM_LAST)),
                    return ge::GRAPH_FAILED);
    } else if (dimNum_ == DIM_NUM_4) { // BSnn
        isTShape_ = false;

        BNum_ = xShape_->GetDim(DIM_NUM_0);
        SNum_ = xShape_->GetDim(DIM_NUM_1);
        totalLength_ = BNum_ * SNum_;
        OP_CHECK_IF(
            BNum_ <= NUM_0, OP_LOGE(context_, "B should be positive, but got %ld", BNum_), return ge::GRAPH_FAILED);
        OP_CHECK_IF(
            SNum_ <= NUM_0, OP_LOGE(context_, "S should be positive, but got %ld", SNum_), return ge::GRAPH_FAILED);
        nNum_ = xShape_->GetDim(DIM_NUM_2);
        OP_CHECK_IF(xShape_->GetDim(dimNum_ - 1) != nNum_,
                    OP_LOGE(context_, "n should be the same, but got %u and %ld", nNum_, xShape_->GetDim(DIM_NUM_LAST)),
                    return ge::GRAPH_FAILED);
    } else {
        OP_LOGE(context_, "x dim should be 3 or 4, but got %u", dimNum_);
        return ge::GRAPH_FAILED;
    }

    OP_CHECK_IF(totalLength_ <= NUM_0,
                OP_LOGE(context_, "totalLength_ should be positive , but got %u", totalLength_),
                return ge::GRAPH_FAILED);
    tilingData_.set_totalLength(totalLength_);

    // UB内存限制： (5t*n*n + 4t*n ) *  inputDtypeSize + 1024*n*n < ubSize或者(3t*n*n + 2t*n ) *  inputDtypeSize +
    // 1024*n*n < ubSize
    //（考虑ubSize预留一定空间，按照190KB计算）
    // 考虑32位对齐，t最小为8
    if (outFlag_ == 1) {
        OP_CHECK_IF(nNum_ > MAX_N_NUM_FLAG1 || nNum_ <= NUM_0,
                    OP_LOGE(context_, "n should not bigger than 12 and should be positive , but got %u", nNum_),
                    return ge::GRAPH_FAILED);
    } else {
        // 推理路径（out_flag=0）：n 受 ALIGN_N=8 限制（DataCopyPad 仅能 pad 到 ALIGN_N）
        OP_CHECK_IF(nNum_ > MAX_N_NUM_FLAG0 || nNum_ <= NUM_0,
                    OP_LOGE(context_, "n should not bigger than 8 and should be positive , but got %u", nNum_),
                    return ge::GRAPH_FAILED);
    }

    tilingData_.set_nNum(nNum_);
    OP_LOGI(context_, "nNum_ is: %ld, total_length is: %ld", nNum_, totalLength_);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus SinkhornTilingBase::CheckOutputShape()
{
    OP_CHECK_IF(outputShape_ == nullptr, OP_LOGE(context_, "output shape is null"), return ge::GRAPH_FAILED);

    size_t xDimNum = xShape_->GetDimNum();
    size_t outputDimNum = outputShape_->GetDimNum();
    OP_CHECK_IF(outputDimNum != xDimNum,
                OP_LOGE(context_, "outputDimNum should be the same as the xDimNum, but got %u", outputDimNum),
                return ge::GRAPH_FAILED);

    if (isTShape_) {
        OP_CHECK_IF(outputShape_->GetDim(DIM_NUM_0) != TNum_ || outputShape_->GetDim(DIM_NUM_1) != nNum_ ||
                        outputShape_->GetDim(DIM_NUM_2) != nNum_,
                    OP_LOGE(context_,
                            "outputShape_ should be [%u,%u,%u], but got [%d,%d,%d].",
                            TNum_,
                            nNum_,
                            nNum_,
                            outputShape_->GetDim(DIM_NUM_0),
                            outputShape_->GetDim(DIM_NUM_1),
                            outputShape_->GetDim(DIM_NUM_2)),
                    return ge::GRAPH_FAILED);
    } else {
        OP_CHECK_IF(outputShape_->GetDim(DIM_NUM_0) != BNum_ || outputShape_->GetDim(DIM_NUM_1) != SNum_ ||
                        outputShape_->GetDim(DIM_NUM_2) != nNum_ || outputShape_->GetDim(DIM_NUM_3) != nNum_,
                    OP_LOGE(context_,
                            "outputShape_ should be [%u,%u,%u,%u], but got [%d,%d,%d,%d].",
                            BNum_,
                            SNum_,
                            nNum_,
                            nNum_,
                            outputShape_->GetDim(DIM_NUM_0),
                            outputShape_->GetDim(DIM_NUM_1),
                            outputShape_->GetDim(DIM_NUM_2),
                            outputShape_->GetDim(DIM_NUM_3)),
                    return ge::GRAPH_FAILED);
    }

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus SinkhornTilingBase::CheckOptionalOutputShape()
{
    // 检验dim值
    OP_CHECK_IF(normOutShape_ == nullptr, OP_LOGE(context_, "normOut shape is null"), return ge::GRAPH_FAILED);

    size_t normOutDimNum = normOutShape_->GetDimNum();
    OP_CHECK_IF(normOutDimNum != dimNum_ + 1,
                OP_LOGE(context_, "normOutDimNum should be the same as %d, but got %d", dimNum_ + 1, normOutDimNum),
                return ge::GRAPH_FAILED);

    OP_CHECK_IF(sumOutShape_ == nullptr, OP_LOGE(context_, "normOut shape is null"), return ge::GRAPH_FAILED);

    size_t sumOutDimNum = sumOutShape_->GetDimNum();
    OP_CHECK_IF(sumOutDimNum != dimNum_,
                OP_LOGE(context_, "sumOutDimNum should be the same as %d, but got %d", dimNum_, sumOutDimNum),
                return ge::GRAPH_FAILED);

    if (isTShape_) {
        OP_CHECK_IF(normOutShape_->GetDim(DIM_NUM_0) != 2 * numIters_ || normOutShape_->GetDim(DIM_NUM_1) != nNum_ ||
                        normOutShape_->GetDim(DIM_NUM_2) != nNum_ || normOutShape_->GetDim(DIM_NUM_3) != TNum_,
                    OP_LOGE(context_,
                            "normOutShape_ should be [%u,%u,%u,%u], but got [%d,%d,%d,%d].",
                            2 * numIters_,
                            nNum_,
                            nNum_,
                            TNum_,
                            normOutShape_->GetDim(DIM_NUM_0),
                            normOutShape_->GetDim(DIM_NUM_1),
                            normOutShape_->GetDim(DIM_NUM_2),
                            normOutShape_->GetDim(DIM_NUM_3)),
                    return ge::GRAPH_FAILED);

        OP_CHECK_IF(sumOutShape_->GetDim(DIM_NUM_0) != 2 * numIters_ || sumOutShape_->GetDim(DIM_NUM_1) != nNum_ ||
                        sumOutShape_->GetDim(DIM_NUM_2) != TNum_,
                    OP_LOGE(context_,
                            "sumOutShape_ should be [%u,%u,%u], but got [%d,%d,%d].",
                            2 * numIters_,
                            nNum_,
                            TNum_,
                            normOutShape_->GetDim(DIM_NUM_0),
                            normOutShape_->GetDim(DIM_NUM_1),
                            normOutShape_->GetDim(DIM_NUM_2)),
                    return ge::GRAPH_FAILED);
    } else {
        OP_CHECK_IF(normOutShape_->GetDim(DIM_NUM_0) != 2 * numIters_ || normOutShape_->GetDim(DIM_NUM_1) != nNum_ ||
                        normOutShape_->GetDim(DIM_NUM_2) != nNum_ || normOutShape_->GetDim(DIM_NUM_3) != BNum_ ||
                        normOutShape_->GetDim(DIM_NUM_4) != SNum_,
                    OP_LOGE(context_,
                            "normOutShape_ should be [%u,%u,%u,%u,%u], but got [%d,%d,%d,%d,%d].",
                            2 * numIters_,
                            nNum_,
                            nNum_,
                            BNum_,
                            SNum_,
                            normOutShape_->GetDim(DIM_NUM_0),
                            normOutShape_->GetDim(DIM_NUM_1),
                            normOutShape_->GetDim(DIM_NUM_2),
                            normOutShape_->GetDim(DIM_NUM_3),
                            normOutShape_->GetDim(DIM_NUM_4)),
                    return ge::GRAPH_FAILED);

        OP_CHECK_IF(sumOutShape_->GetDim(DIM_NUM_0) != 2 * numIters_ || sumOutShape_->GetDim(DIM_NUM_1) != nNum_ ||
                        sumOutShape_->GetDim(DIM_NUM_2) != BNum_ || sumOutShape_->GetDim(DIM_NUM_3) != SNum_,
                    OP_LOGE(context_,
                            "sumOutShape_ should be [%u,%u,%u,%u], but got [%d,%d,%d,%d].",
                            2 * numIters_,
                            nNum_,
                            BNum_,
                            SNum_,
                            normOutShape_->GetDim(DIM_NUM_0),
                            normOutShape_->GetDim(DIM_NUM_1),
                            normOutShape_->GetDim(DIM_NUM_2),
                            sumOutShape_->GetDim(DIM_NUM_3)),
                    return ge::GRAPH_FAILED);
    }
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus SinkhornTilingBase::SplitCores()
{
    // 核间切分：在数据维度上进行核间切分 每个核处理的t数量尽量均匀
    int64_t aivNum = static_cast<int64_t>(aicoreParams_.blockDim);
    int64_t perCoreElements = CeilDiv(totalLength_, aivNum);

    // 限核：推理路径（out_flag=0）允许更细粒度分核（MIN=8），提高小T场景并行度
    //       训练路径（out_flag=1）保持原有限制（MIN=32）
    int64_t minPerCore = static_cast<int64_t>((outFlag_ == 0) ? MIN_PER_CORE_ELEMENTS_INFER : MIN_PER_CORE_ELEMENTS);
    if (perCoreElements < minPerCore && totalLength_ >= minPerCore) {
        perCoreElements = minPerCore;
    } else if (outFlag_ == 1) {
        // 训练路径：对齐到 8 元素边界
        perCoreElements = AlignUp(perCoreElements, BIT_WIDTH_32 / inputDtypeSize_);
    }
    // 推理路径（outFlag_==0）：不做 AlignUp，直接用 CeilDiv 结果，避免越界
    int64_t needCoreNum = CeilDiv(totalLength_, perCoreElements);
    int64_t lastCoreElements = totalLength_ - perCoreElements * (needCoreNum - 1);

    tilingData_.set_needCoreNum(needCoreNum);
    tilingData_.set_perCoreElements(perCoreElements);
    tilingData_.set_lastCoreElements(lastCoreElements);

    OP_LOGI(context_,
            "Core splitting: needCoreNum=%ld, perCoreElements=%ld, lastCoreElements=%ld",
            needCoreNum,
            perCoreElements,
            lastCoreElements);

    tAlign_ = CalTAlign();
    OP_CHECK_IF(tAlign_ <= NUM_0,
                OP_LOGE(context_, "tAlign_ should be positive , but got %u", tAlign_),
                return ge::GRAPH_FAILED);

    // 核内切分：头核 perCorePerLoopElements天然32位对齐
    int64_t perCorePerLoopElements = std::min(perCoreElements, tAlign_);
    int64_t perCoreLoops = CeilDiv(perCoreElements, perCorePerLoopElements);
    int64_t perCoreLastLoopElements = perCoreElements - perCorePerLoopElements * (perCoreLoops - 1);

    // 核内切分：尾核
    int64_t lastCorePerLoopElements = std::min(lastCoreElements, tAlign_);
    int64_t lastCoreLoops = CeilDiv(lastCoreElements, lastCorePerLoopElements);
    int64_t lastCoreLastLoopElements = lastCoreElements - lastCorePerLoopElements * (lastCoreLoops - 1);

    tilingData_.set_perCorePerLoopElements(perCorePerLoopElements);
    tilingData_.set_perCoreLoops(perCoreLoops);
    tilingData_.set_perCoreLastLoopElements(perCoreLastLoopElements);
    tilingData_.set_lastCorePerLoopElements(lastCorePerLoopElements);
    tilingData_.set_lastCoreLoops(lastCoreLoops);
    tilingData_.set_lastCoreLastLoopElements(lastCoreLastLoopElements);

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus SinkhornTilingBase::DoOpTiling()
{
    auto ret = CheckInputShape();
    if (ret != ge::GRAPH_SUCCESS) {
        return ret;
    }

    ret = CheckOutputShape();
    if (ret != ge::GRAPH_SUCCESS) {
        return ret;
    }

    if (outFlag_ == 1) {
        ret = CheckOptionalOutputShape();
        if (ret != ge::GRAPH_SUCCESS) {
            return ret;
        }
    }

    ret = SplitCores();
    if (ret != ge::GRAPH_SUCCESS) {
        return ret;
    }

    // 预计算 reduceMask（仅推理路径 out_flag=0 使用）
    // 动态 mask：低 n_ 位有效，重复 8 次填满 64bit
    // e.g. n=4: 0x0F → 0x0F0F0F0F0F0F0F0F
    //      n=8: 0xFF → 0xFFFFFFFFFFFFFFFF
    if (outFlag_ == 0) {
        uint64_t rowBits = (nNum_ < 64) ? ((1ULL << nNum_) - 1ULL) : ~0ULL;
        uint64_t fullMask = 0;
        for (uint64_t i = 0; i < 8; ++i) {
            fullMask |= (rowBits << (i * 8));
        }
        tilingData_.set_reduceMask(fullMask);
    } else {
        // 训练路径不使用，设为 0
        tilingData_.set_reduceMask(0);
    }

    return ge::GRAPH_SUCCESS;
}

ge::graphStatus SinkhornTilingBase::DoLibApiTiling()
{
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus SinkhornTilingBase::GetWorkspaceSize()
{
    // 计算 workspace 大小
    workspaceSize_ = DEFAULT_WORKSPACE_SIZE;
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus SinkhornTilingBase::PostTiling()
{
    context_->SetBlockDim(tilingData_.get_needCoreNum());
    size_t *currentWorkspace = context_->GetWorkspaceSizes(1);
    currentWorkspace[0] = workspaceSize_;
    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
    return ge::GRAPH_SUCCESS;
}

uint64_t SinkhornTilingBase::GetTilingKey() const
{
    // out_flag=0 → 推理路径（DataCopyPad 模板）
    // out_flag=1 → 训练路径（Transpose 模板，保持原有行为）
    return (outFlag_ == 0) ? TILING_KEY_INFER : TILING_KEY_GENERALIZED;
}

void SinkhornTilingBase::Reset()
{
    opName_ = nullptr;
    totalLength_ = 0;
    tAlign_ = 0;
    outFlag_ = 0;
    eps_ = 1e-6F;
    numIters_ = 20;
    inputDtypeSize_ = 4;
    nNum_ = 0;
    TNum_ = 0;
    BNum_ = 0;
    SNum_ = 0;
    isTShape_ = false;
    return;
}

