71	static ge::graphStatus CheckParams(const gert::TilingContext *context)
72	{
73	    if (context->GetAttrs() != nullptr && context->GetInputShape(QUERY_INPUT_INDEX) != nullptr &&
74	        context->GetInputShape(KEY_INPUT_INDEX) != nullptr && context->GetInputShape(VALUE_INPUT_INDEX) != nullptr) {
75	        auto &valueShape = context->GetInputShape(VALUE_INPUT_INDEX)->GetStorageShape();
76	        auto &keyShape = context->GetInputShape(KEY_INPUT_INDEX)->GetStorageShape();
77	        auto &queryShape = context->GetInputShape(QUERY_INPUT_INDEX)->GetStorageShape();
78	        const char *inputLayout = context->GetAttrs()->GetAttrPointer<char>(INPUTLAYOUT_ATTRS_INDEX);
79	        if (strlen(inputLayout) == 3) { // 3: BSH or SBH
80	            if (inputLayout[0] == 'B') {
81	                // layout is BSH
82	                OP_CHECK_IF((queryShape.GetDim(0) != keyShape.GetDim(0)),
83	                            OP_LOGE(context, "query or key shape is invalid"),
84	                            return ge::GRAPH_FAILED);
85	            } else {
86	                if (inputLayout[0] == 'T') { // TND  N1 != N2
87	                    // q_D != k_D
88	                    OP_CHECK_IF((queryShape.GetDim(2) != keyShape.GetDim(2)),
89	                                OP_LOGE(context, "query or key shape is invalid"),
90	                                return ge::GRAPH_FAILED);
91	                    return ge::SUCCESS;
92	                }
93	                // layout is SBH
94	                OP_CHECK_IF((queryShape.GetDim(1) != keyShape.GetDim(1)),
95	                            OP_LOGE(context, "query or key shape is invalid"),
96	                            return ge::GRAPH_FAILED);
97	            }
98	            // kD < vD
99	            OP_CHECK_IF((keyShape.GetDim(2) < valueShape.GetDim(2)),
100	                        OP_LOGE(context, "key or value shape is invalid"),
101	                        return ge::GRAPH_FAILED);
102	        } else if (strlen(inputLayout) == 4) { // 4: layout is BNSD or BSND
103	            OP_CHECK_IF((queryShape.GetDim(0) != keyShape.GetDim(0)),
104	                        OP_LOGE(context, "query or key shape is invalid"),
105	                        return ge::GRAPH_FAILED);
106	            OP_CHECK_IF((queryShape.GetDim(3) != keyShape.GetDim(3)),
107	                        OP_LOGE(context, "query or key shape is invalid"),
108	                        return ge::GRAPH_FAILED);
109	            OP_CHECK_IF((keyShape.GetDim(3) < valueShape.GetDim(3)),
110	                        OP_LOGE(context, "key or value shape is invalid"),
111	                        return ge::GRAPH_FAILED);
112	        } else {
113	            OP_LOGW(context, "invalid input_layout[%s].", inputLayout);
114	            return ge::GRAPH_FAILED;
115	        }
116	        return ge::SUCCESS;
117	    }
118	    OP_LOGW(context, "fail to get shape or attr from context");
119	    return ge::GRAPH_FAILED;
120	}
