122	static bool GetEmptyArgs(EmptyArgs &emptyArgs,
123	                         gert::TilingContext *context,
124	                         const uint32_t &coreNum,
125	                         const uint64_t &attentionOutShapeSize,
126	                         const int64_t &softmaxSumShapeSize)
127	{
128	    emptyArgs.coreNum = coreNum;
129	    OP_CHECK_IF((coreNum <= 0), OP_LOGE(context, "platform info is invalid, coreNum=%u.", coreNum), return false);
130	    auto kernelType = context->GetInputDesc(KEY_INPUT_INDEX)->GetDataType();
131	    OP_CHECK_IF((kernelType != ge::DT_FLOAT16 && kernelType != ge::DT_FLOAT && kernelType != ge::DT_BF16),
132	                OP_LOGE(context, "kernelType is invalid, kernelType is %d.", kernelType),
133	                return false);
134	    uint32_t kernelTypeSize = ge::GetSizeByDataType(kernelType);
135	    OP_CHECK_IF((kernelTypeSize <= 0),
136	                OP_LOGE(context, "kernelType size is invalid, kernelType size is %u.", kernelTypeSize),
137	                return false);
138	    // 计算 MIN_COPY_UINT_SIZE 块数
139	    emptyArgs.attentionOutBlockSize =
140	        Ceil(static_cast<uint32_t>(attentionOutShapeSize) * kernelTypeSize, MIN_COPY_UINT_SIZE);
141	    if (attentionOutShapeSize != 0ULL) {
142	        if (static_cast<uint64_t>(emptyArgs.attentionOutBlockSize % coreNum) == 0ULL) {
143	            emptyArgs.attentionOutTailCoreDataSize = 0ULL;
144	            emptyArgs.attentionOutFormerNum = coreNum;
145	            emptyArgs.attentionOutTailNum = 0U;
146	            emptyArgs.attentionOutSingleCoreDataSize =
147	                emptyArgs.attentionOutBlockSize / coreNum * MIN_COPY_UINT_SIZE / kernelTypeSize;
148	            emptyArgs.attentionOutLastCoreDataSize =
149	                emptyArgs.attentionOutSingleCoreDataSize -
150	                (emptyArgs.attentionOutBlockSize * MIN_COPY_UINT_SIZE / kernelTypeSize - attentionOutShapeSize);
151	            emptyArgs.attentionOutLastCoreIndex =
152	                static_cast<uint64_t>(emptyArgs.attentionOutFormerNum - 1U) * emptyArgs.attentionOutSingleCoreDataSize;
153	        } else {
154	            emptyArgs.attentionOutTailCoreDataSize =
155	                emptyArgs.attentionOutBlockSize / coreNum * MIN_COPY_UINT_SIZE / kernelTypeSize;
156	            emptyArgs.attentionOutSingleCoreDataSize =
157	                emptyArgs.attentionOutTailCoreDataSize + MIN_COPY_UINT_SIZE / kernelTypeSize;
158	            if (emptyArgs.attentionOutBlockSize > coreNum) {
159	                emptyArgs.attentionOutFormerNum = static_cast<uint32_t>(emptyArgs.attentionOutBlockSize % coreNum);
160	                emptyArgs.attentionOutTailNum = coreNum - emptyArgs.attentionOutFormerNum;
161	                emptyArgs.attentionOutLastCoreIndex =
162	                    static_cast<uint64_t>(emptyArgs.attentionOutFormerNum) * emptyArgs.attentionOutSingleCoreDataSize +
163	                    static_cast<uint64_t>(emptyArgs.attentionOutTailNum - 1U) * emptyArgs.attentionOutTailCoreDataSize;
164	                emptyArgs.attentionOutLastCoreDataSize =
165	                    emptyArgs.attentionOutTailCoreDataSize -
166	                    (emptyArgs.attentionOutSingleCoreDataSize * emptyArgs.attentionOutFormerNum +
167	                     emptyArgs.attentionOutTailCoreDataSize * emptyArgs.attentionOutTailNum - attentionOutShapeSize);
168	            } else {
169	                emptyArgs.attentionOutFormerNum = emptyArgs.attentionOutBlockSize;
170	                emptyArgs.attentionOutTailNum = 0U;
171	                emptyArgs.attentionOutLastCoreIndex = static_cast<uint64_t>(emptyArgs.attentionOutFormerNum - 1U) *
172	                                                      emptyArgs.attentionOutSingleCoreDataSize;
173	                emptyArgs.attentionOutLastCoreDataSize =
174	                    emptyArgs.attentionOutSingleCoreDataSize -
175	                    (emptyArgs.attentionOutFormerNum * emptyArgs.attentionOutSingleCoreDataSize -
176	                     attentionOutShapeSize);
177	            }
178	        }
179	    } else {
180	        emptyArgs.attentionOutFormerNum = 0U;
181	        emptyArgs.attentionOutTailNum = 0U;
182	        emptyArgs.attentionOutSingleCoreDataSize = 0ULL;
183	        emptyArgs.attentionOutTailCoreDataSize = 0ULL;
184	        emptyArgs.attentionOutLastCoreDataSize = 0ULL;
185	        emptyArgs.attentionOutLastCoreIndex = 0ULL;
186	    }
187	
188	    uint32_t floatDataSize = ge::GetSizeByDataType(ge::DT_FLOAT);
189	    OP_CHECK_IF(
190	        (floatDataSize <= 0), OP_LOGE(context, "float data size is invalid, size is %u.", floatDataSize), return false);
191	    // softmaxSum 和 softmaxMax 输出为 fp32
192	    emptyArgs.softmaxSumBlockSize =
193	        Ceil(static_cast<uint32_t>(softmaxSumShapeSize) * floatDataSize, MIN_COPY_UINT_SIZE);
194	    if (static_cast<uint64_t>(emptyArgs.softmaxSumBlockSize % coreNum) == 0ULL) {
195	        emptyArgs.softmaxMaxSingleCoreDataSize =
196	            emptyArgs.softmaxSumBlockSize / coreNum * MIN_COPY_UINT_SIZE / floatDataSize;
197	        emptyArgs.softmaxMaxTailCoreDataSize = 0U;
198	        emptyArgs.softmaxMaxFormerNum = coreNum;
199	        emptyArgs.softmaxMaxTailNum = 0U;
200	    } else {
201	        if (emptyArgs.softmaxSumBlockSize > coreNum) {
202	            emptyArgs.softmaxMaxFormerNum = static_cast<uint32_t>(emptyArgs.softmaxSumBlockSize % coreNum);
203	            emptyArgs.softmaxMaxTailNum = coreNum - emptyArgs.softmaxMaxFormerNum;
204	        } else {
205	            emptyArgs.softmaxMaxFormerNum = emptyArgs.softmaxSumBlockSize;
206	            emptyArgs.softmaxMaxTailNum = 0U;
207	        }
208	        emptyArgs.softmaxMaxTailCoreDataSize =
209	            emptyArgs.softmaxSumBlockSize / coreNum * MIN_COPY_UINT_SIZE / floatDataSize;
210	        emptyArgs.softmaxMaxSingleCoreDataSize =
211	            emptyArgs.softmaxMaxTailCoreDataSize + MIN_COPY_UINT_SIZE / floatDataSize;
212	    }
213	    emptyArgs.aivActualNum = std::max((emptyArgs.attentionOutFormerNum + emptyArgs.attentionOutTailNum),
214	                                      (emptyArgs.softmaxMaxFormerNum + emptyArgs.softmaxMaxTailNum));
215	    return true;
216	}
